begin;create extension if not exists pgtap with schema extensions;select no_plan();
\ir helpers/signal_wave_fixtures.sql
select pg_temp.signal_case_setup(n)from generate_series(1,8)n;
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(1,'2000'),pg_temp.signal_case_id(1,'5000'))->>'state','ORDERED_REQUIRED','default FIFO is unchanged');
select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(1,'first'));select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(1,'second'));
select is(private.signal_claim_fixture_v1(pg_temp.signal_case_id(1,'2000'))->>'state','LEASED','accepted single-claim path still usable');
select is(private.signal_claim_fixture_v1(pg_temp.signal_case_id(1,'2000'))->>'state','NO_LEASE','default destination cannot get concurrent lease');
select throws_ok($$select private.signal_wave_configure_fixture_v1(pg_temp.signal_case_id(1,'2000'),pg_temp.signal_case_id(1,'5000'),2)$$,'42501','SIGNAL_WAVE_PENDING_OBLIGATION','cannot change ordering around in-flight work');
select private.signal_wave_configure_fixture_v1(pg_temp.signal_case_id(n,'2000'),pg_temp.signal_case_id(n,'5000'),2)from generate_series(2,8)n;
select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(2,'msg-'||n))from generate_series(1,3)n;
create temp table wave_result as select private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(2,'2000'),pg_temp.signal_case_id(2,'5000'))v;
select is((select jsonb_array_length(v->'items')from wave_result),2,'exact bounded2 prepared');
select is((select count(*)::int from private.signal_attempts where tenant_id=pg_temp.signal_case_id(2,'2000')),2,'each durable attempt exists before fake dispatch');
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(2,'2000'),pg_temp.signal_case_id(2,'5000'))->>'state','RECOVERY_REQUIRED','lost prepare response cannot emit same payload again');
select private.signal_finish_fixture_v1(pg_temp.signal_case_id(2,'2000'),(v#>>'{items,0,delivery_id}')::uuid,(v#>>'{items,0,lease_token}')::uuid,'{"outcome":"UNKNOWN","retry_after_ms":null}')from wave_result;
select private.signal_finish_fixture_v1(pg_temp.signal_case_id(2,'2000'),(v#>>'{items,1,delivery_id}')::uuid,(v#>>'{items,1,lease_token}')::uuid,pg_temp.signal_ack(v#>'{items,1,payload}'))from wave_result;
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(2,'2000'),pg_temp.signal_case_id(2,'5000'))->>'state','RECOVERY_REQUIRED','one unknown outcome blocks further destination work');
select is((select count(*)::int from private.signal_deliveries where tenant_id=pg_temp.signal_case_id(2,'2000')and status='PENDING'),1,'pending obligation not discarded');
select is((select count(*)::int from private.signal_deliveries where tenant_id=pg_temp.signal_case_id(2,'2000')and status='FAKE_CONFIRMED'),1,'only actually acknowledged sibling confirmed');
select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(3,'a'));
select private.signal_record_fixture_v1(jsonb_set(pg_temp.signal_dispatch_input(3,'b')::jsonb,'{reply_to}','"a"')::text);
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(3,'2000'),pg_temp.signal_case_id(3,'5000'))->>'state','ORDERED_REQUIRED','reply dependency never parallelized');
select is((select count(*)::int from private.signal_attempts where tenant_id=pg_temp.signal_case_id(3,'2000')),0,'whole wave validated before partial lease or begin');
select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(4,'a'));
select private.signal_record_fixture_v1(jsonb_set(pg_temp.signal_dispatch_input(4,'b')::jsonb,'{interpretation,action}','"CANCEL"')::text);
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(4,'2000'),pg_temp.signal_case_id(4,'5000'))->>'state','ORDERED_REQUIRED','lifecycle update cannot join independent OPEN wave');
select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(5,'a'));select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(5,'b'));
create temp table rate_wave as select private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(5,'2000'),pg_temp.signal_case_id(5,'5000'))v;
select private.signal_finish_fixture_v1(pg_temp.signal_case_id(5,'2000'),(v#>>'{items,0,delivery_id}')::uuid,(v#>>'{items,0,lease_token}')::uuid,'{"outcome":"RATE_LIMITED","retry_after_ms":5000}')from rate_wave;
select private.signal_finish_fixture_v1(pg_temp.signal_case_id(5,'2000'),(v#>>'{items,1,delivery_id}')::uuid,(v#>>'{items,1,lease_token}')::uuid,pg_temp.signal_ack(v#>'{items,1,payload}'))from rate_wave;
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(5,'2000'),pg_temp.signal_case_id(5,'5000'))->>'state','ORDERED_REQUIRED','rate-limit retry retains accepted ordered/backoff path');
select ok((select available_at>clock_timestamp()from private.signal_deliveries where tenant_id=pg_temp.signal_case_id(5,'2000')and status='RETRY'),'explicit retry-after respected');
select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(6,'a'));select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(6,'b'));
create temp table stale_wave as select private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(6,'2000'),pg_temp.signal_case_id(6,'5000'))v;
select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(6,'a',2,'EDIT'));
select is((select private.signal_finish_fixture_v1(pg_temp.signal_case_id(6,'2000'),(v#>>'{items,0,delivery_id}')::uuid,(v#>>'{items,0,lease_token}')::uuid,pg_temp.signal_ack(v#>'{items,0,payload}'))->>'state'from stale_wave),'STALE_ACK','late ACK cannot authorize a superseded revision');
select is((select private.signal_finish_fixture_v1(pg_temp.signal_case_id(7,'2000'),(v#>>'{items,1,delivery_id}')::uuid,(v#>>'{items,1,lease_token}')::uuid,pg_temp.signal_ack(v#>'{items,1,payload}'))->>'state'from stale_wave),'FENCED','foreign tenant cannot complete prepared wave');
update private.signal_controls set enabled=false where tenant_id=pg_temp.signal_case_id(7,'2000');
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(7,'2000'),pg_temp.signal_case_id(7,'5000'))->>'state','PAUSED','global fixture pause preserved');
select throws_ok($$select private.signal_wave_configure_fixture_v1(pg_temp.signal_case_id(8,'2000'),pg_temp.signal_case_id(8,'5000'),3)$$,'22023','SIGNAL_WAVE_POLICY_INVALID','hard width ceiling cannot be increased');
select ok(not has_function_privilege('authenticated','private.signal_wave_prepare_fixture_v1(uuid,uuid)','EXECUTE'),'no browser writer');
select ok(not has_function_privilege('service_role','private.signal_wave_prepare_fixture_v1(uuid,uuid)','EXECUTE'),'no service-role writer');
select is((select max(claims)::int from private.signal_deliveries where tenant_id=pg_temp.signal_case_id(2,'2000')),1,'no duplicate claim on uncertain replay');
select private.signal_fixture_configure_v1(pg_temp.signal_case_id(8,'2000'),pg_temp.signal_case_id(8,'4000'),pg_temp.signal_case_id(8,'3001'),pg_temp.signal_case_id(8,'5001'),pg_temp.signal_case_id(8,'6001'),'Independent destination','fixture:second-source','fixture:second-destination',true);
select private.signal_wave_configure_fixture_v1(pg_temp.signal_case_id(8,'2000'),pg_temp.signal_case_id(8,'5001'),2);
select private.signal_record_fixture_v1(pg_temp.signal_dispatch_input(8,'first-'||n))from generate_series(1,2)n;
select private.signal_record_fixture_v1(jsonb_set(pg_temp.signal_dispatch_input(8,'independent-'||n)::jsonb,'{source_id}',to_jsonb(pg_temp.signal_case_id(8,'3001')::text))::text)from generate_series(1,2)n;
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(8,'2000'),pg_temp.signal_case_id(8,'5000'))->>'state','PREPARED','first destination may have a pending fake effect');
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(8,'2000'),pg_temp.signal_case_id(8,'5001'))->>'state','PREPARED','independent destination is not blocked by another destination lease');
select is(private.signal_wave_prepare_fixture_v1(pg_temp.signal_case_id(8,'2000'),pg_temp.signal_case_id(7,'5000'))->>'state','ORDERED_REQUIRED','foreign destination does not expose a lease or authority');
select * from finish();rollback;
